<?php require '../config/database.php';auth();if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO products(name,barcode,category,purchase_price,sale_price,quantity,min_quantity,description) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$_POST['name'],$_POST['barcode'],$_POST['category'],(float)$_POST['purchase_price'],(float)$_POST['sale_price'],(int)$_POST['quantity'],(int)$_POST['min_quantity'],$_POST['description']]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>إضافة منتج</h1><form method="post"><label>اسم المنتج</label><input name="name" required><label>الباركود</label><input name="barcode"><label>التصنيف</label><input name="category"><label>سعر الشراء</label><input type="number" step="0.01" name="purchase_price" value="0"><label>سعر البيع</label><input type="number" step="0.01" name="sale_price" value="0"><label>الكمية</label><input type="number" name="quantity" value="0"><label>الحد الأدنى</label><input type="number" name="min_quantity" value="5"><label>الوصف</label><textarea name="description"></textarea><button>حفظ</button></form></main>
